import { Icon } from "@/registry/erbium/ui/icon";

import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";

export function InputGroupInlineStart() {
  return (
    <Field className="max-w-sm">
      <FieldLabel>Input</FieldLabel>
      <InputGroup>
        <InputGroupInput placeholder="Search..." />
        <InputGroupAddon align="inline-start">
          <Icon name="search-01" className="text-muted-foreground" />
        </InputGroupAddon>
      </InputGroup>
      <FieldDescription>Icon positioned at the start.</FieldDescription>
    </Field>
  );
}

import { InputGroupInlineStart } from "../examples/input-group-inline-start";

const Example = () => <InputGroupInlineStart />;

export default Example;
